// 33 m² apartment
// Generated by tools/migrate.mjs (Phase 1). build() adds this apartment's slabs, walls, floors and
// furniture to the shared scene; everything else comes from the engine.
import * as THREE from 'three';
import { PointerLockControls } from 'three/addons/controls/PointerLockControls.js';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { GTAOPass } from 'three/addons/postprocessing/GTAOPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
import { RectAreaLightUniformsLib } from 'three/addons/lights/RectAreaLightUniformsLib.js';
import { Sky } from 'three/addons/objects/Sky.js';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { X, Z } from '../engine/plan.js';
import {
  FACE, H, M, P, RBG, at, baseCabB, bedB, box, caneChairB, canvasTex, ceilingGroup, colliders,
  concreteTex, cove, curtain, cylinder, drumB, floor, floorWoodTex, flutedConsoleB, fridgeB, item,
  lathe, mesh, plantB, porcelainTex, railingBars, rainShower, rb, roundCoffeeB, rug, sanca, sofaB,
  std, succulent, tableLamp, terraceTex, tileBox, toiletB, towelRail, tvSlim, upperCabB, vanity2B,
  wall, wardrobeB, woodClad, world, worldRb,
} from '../engine/core.js';

export function build() {
  // ---------------------------------------------------------------------------
  // SLABS, FLOORS, CEILING
  // ---------------------------------------------------------------------------
  for (const [a, b, c, d] of [[997, 202, 1315, 997], [713, 280, 997, 997]]) {
    box(a, b, c, d, -0.3, 0, M.extWall, { collide: false });
    box(a, b, c, d, H, H + 0.3, M.extWall, { collide: false, parent: ceilingGroup });
    const w = X(c) - X(a), dd = Z(d) - Z(b);
    const ce = new THREE.Mesh(new THREE.PlaneGeometry(w, dd), M.ceiling);
    ce.rotation.x = Math.PI / 2; ce.position.set(X(a) + w / 2, H - 0.001, Z(b) + dd / 2); ce.receiveShadow = true;
    ceilingGroup.add(ce);
  }
  floor(1000, 228, 1290, 810, porcelainTex, 0.9, 0.22);                  // cozinha + estar / jantar
  floor(737, 458, 1000, 797, floorWoodTex, 1.6, 0.5, 0.003);              // suíte
  floor(737, 305, 1000, 458, porcelainTex, 0.9, 0.25, 0.004);             // banho
  floor(978, 810, 1290, 968, terraceTex, 0.9, 0.5, 0.002);                // terraço
  floor(737, 822, 968, 968, concreteTex, 1.0, 0.8, 0.002);                // área técnica

  // ---------------------------------------------------------------------------
  // WALLS (traced from the 33 m² plan)
  // ---------------------------------------------------------------------------
  wall(997, 202, 1315, 228, [{ from: 1085, to: 1180 }]);                  // FRONT DOOR (top of the kitchen)
  wall(713, 280, 1000, 305, [{ from: 742, to: 815, sill: 1.6, glass: 'window' }]);   // banho window
  wall(997, 202, 1020, 465);                                              // outer step | banho  (kitchen west wall)
  wall(713, 280, 737, 997);                                               // west façade
  wall(1290, 228, 1315, 997);                                             // east party wall
  wall(737, 450, 1000, 465, [{ from: 922, to: 985 }]);                    // banho | suíte (banho door)
  wall(1000, 465, 1020, 797, [{ from: 485, to: 572 }]);                   // suíte | estar (suíte door)
  wall(737, 797, 1000, 822, [{ from: 785, to: 968, sill: 1.0, top: 2.2, glass: 'window' }]);   // suíte window → área técnica
  wall(1000, 797, 1290, 822, [{ from: 1035, to: 1160, top: 2.3, glass: 'open' }, { from: 1160, to: 1285, top: 2.3, glass: 'fixed' }]);  // sliding door → terraço
  wall(968, 822, 980, 968);                                               // terraço | área técnica
  box(1020, 228, 1068, 283, 0, H, M.wall);                                // shaft in the kitchen corner
  box(737, 822, 775, 870, 0, H, M.wall);                                  // shaft in the área técnica
  wall(737, 968, 968, 997, [{ from: 755, to: 960, sill: 0.2, top: 2.3, glass: 'window' }]);    // área técnica louvre
  railingBars(980, 968, 1290, 990);
  // front door leaf + handle
  box(1087, 211, 1178, 217, 0.005, 2.095, P.walnut);
  for (const [z0, z1] of [[217, 220], [208, 211]]) {
    box(1160, z0, 1163, z1, 0.98, 1.08, P.brass, { collide: false });
    box(1146, z0, 1163, z1, 1.02, 1.045, P.brass, { collide: false });
  }
  // building corridor / elevator lobby outside the front door
  box(845, 45, 1715, 202, -0.3, 0, M.extWall, { collide: false });
  floor(860, 60, 1700, 202, porcelainTex, 0.9, 0.22, 0.002);
  box(845, 45, 1715, 202, H, H + 0.3, M.extWall, { collide: false, parent: ceilingGroup });
  box(845, 45, 1715, 202, H - 0.012, H, M.ceiling, { collide: false, cast: false, parent: ceilingGroup });
  wall(845, 45, 1715, 60);
  wall(845, 60, 860, 202);
  wall(1700, 60, 1715, 202);
  wall(860, 202, 997, 215);
  wall(1315, 202, 1700, 228, [{ from: 1480, to: 1565 }]);                 // neighbour's door
  box(1482, 211, 1563, 217, 0.005, 2.095, P.walnut);
  for (const ex of [1180, 1310]) {
    box(ex, 60, ex + 101, 63, 0, 2.15, M.steel, { collide: false });
    box(ex + 50, 62.5, ex + 51, 63.3, 0.02, 2.13, P.black, { collide: false });
    box(ex + 108, 60, ex + 115, 62, 1.0, 1.25, P.black, { collide: false });
    box(ex + 110, 61.5, ex + 113, 62.6, 1.07, 1.1, P.led, { collide: false });
  }

  // ---------------------------------------------------------------------------
  // HELPERS – framed art, roller blind on a wall running along z, wall sconce, round table
  // ---------------------------------------------------------------------------
  function artMat(bg, cols) {
    const t = canvasTex(512, 640, (g, w, h) => {
      g.fillStyle = bg; g.fillRect(0, 0, w, h);
      cols.forEach((c, i) => {
        g.fillStyle = c; g.globalAlpha = 0.85;
        g.beginPath();
        if (i % 3 === 0) g.arc(w * (0.3 + 0.4 * Math.random()), h * (0.25 + 0.5 * Math.random()), w * (0.16 + 0.12 * Math.random()), 0, Math.PI * 2);
        else if (i % 3 === 1) { const y = h * (0.45 + 0.35 * Math.random()); g.moveTo(0, y); g.bezierCurveTo(w * 0.3, y - h * 0.2, w * 0.7, y + h * 0.15, w, y - h * 0.05); g.lineTo(w, h); g.lineTo(0, h); }
        else g.rect(w * 0.15 * Math.random(), h * 0.1, w * (0.25 + 0.3 * Math.random()), h * 0.06);
        g.fill();
      });
      g.globalAlpha = 1;
    });
    t.wrapS = t.wrapT = THREE.ClampToEdgeWrapping;
    return std({ map: t, roughness: 0.9 });
  }
  function wallArt(px, pz, w, h, yc, face, mat) {      // walnut float frame + print; face = direction it looks
    const g = new THREE.Group();
    rb(g, w, h, 0.03, P.walnut, 0, -h / 2, 0.015, 0.004);
    rb(g, w - 0.04, h - 0.04, 0.012, P.lacquer, 0, -h / 2 + 0.02, 0.026, 0.002);                   // mat board
    mesh(g, new THREE.PlaneGeometry(w - 0.1, h - 0.1), mat, 0, 0, 0.0335, 0, 0, 0, false);
    g.position.set(X(px), yc, Z(pz)); g.rotation.y = FACE[face]; world.add(g);
  }
  function rollerBlindZ(z0p, z1p, xWallP, dir, top = 2.2) {
    const z0 = Z(z0p), z1 = Z(z1p), xf = X(xWallP) + dir * 0.06, zc = (z0 + z1) / 2;
    mesh(world, RBG(0.08, 0.08, z1 - z0, 0.02), P.lacquer, xf, top - 0.04, zc);
    mesh(world, new THREE.PlaneGeometry(z1 - z0 - 0.04, 0.45), std({ color: '#e9e3d8', roughness: 1, side: THREE.DoubleSide, transparent: true, opacity: 0.92 }), xf, top - 0.3, zc, 0, Math.PI / 2, 0, false);
  }
  function sconce(px, pz, y, face) {                    // black wall arm + opal globe (emissive only, no extra light)
    const g = new THREE.Group();
    cylinder(g, 0.04, 0.04, 0.015, P.brass, 0, 0, 0.0075, 24).rotation.x = Math.PI / 2;
    mesh(g, new THREE.CylinderGeometry(0.007, 0.007, 0.14, 10), P.black, 0, 0, 0.08, Math.PI / 2);
    mesh(g, new THREE.SphereGeometry(0.065, 24, 16), P.shade, 0, 0.02, 0.17, 0, 0, 0, false);
    g.position.set(X(px), y, Z(pz)); g.rotation.y = FACE[face]; world.add(g);
  }
  function roundTableB(r = 0.4) {                    // walnut round top on a flared pedestal, succulent bowl
    const g = new THREE.Group(), top = 0.74;
    cylinder(g, r, r, 0.03, P.walnut, 0, top - 0.03, 0, 64);
    lathe(g, [[0, 0], [0.22, 0], [0.22, 0.02], [0.06, 0.06], [0.045, top - 0.08], [0.12, top - 0.035], [0, top - 0.035]], P.walnut, 0, 0, 0, 40);
    lathe(g, [[0, 0], [0.08, 0], [0.13, 0.06], [0.125, 0.065], [0, 0.02]], P.ceramic, 0, top, 0, 32);
    succulent(g, 0, top + 0.05, 0, 0.9);
    return g;
  }

  // ---------------------------------------------------------------------------
  // SUÍTE (2.40 × 2.95 m) – per the plan: wardrobe on the north wall, queen bed with its head on the
  // west wall between two round nightstands, rug, curtain on the window to the área técnica
  // ---------------------------------------------------------------------------
  item(wardrobeB, 737, 467, 918, 527, 's');
  woodClad(737, 535, 740, 797, 0, 1.3);                                   // walnut headboard wall
  box(737, 535, 741, 797, 1.3, 1.315, P.walnut, { collide: false });
  box(740, 540, 741, 792, 1.285, 1.295, P.led, { collide: false, cast: false });
  rug(785, 545, 965, 768, P.rugGray);
  item(bedB, 741, 588, 962, 762, 'e', true, { headH: 1.15 });
  item(drumB, 744, 548, 785, 586, 's'); item(drumB, 744, 764, 785, 796, 's');
  tableLamp(X(765), 0.55, Z(567)); tableLamp(X(765), 0.55, Z(780));
  curtain(785, 968, 797, -1);
  sanca(737, 527, 1000, 797, 32, 0.12);

  // ---------------------------------------------------------------------------
  // BANHO (2.37 × 1.30 m) – shower on the west with a glass screen, toilet, granite vanity,
  // quartzite feature wall with LED cove
  // ---------------------------------------------------------------------------
  box(827, 305, 1000, 306.5, 0, H, P.quartz, { collide: false }); cove(Z(306.5), X(827), X(1000), 1, true);
  item(vanity2B, 915, 307, 998, 362, 's');
  item(toiletB, 835, 307, 887, 375, 's');
  box(823, 306.5, 827, 395, 0, 2.0, M.glass, { cast: false }); box(822, 393, 828, 396, 0, 2.0, P.black, { collide: false });
  tileBox(737, 306.5, 738.5, 450, 0, H); tileBox(737, 305, 823, 306.5, 0, 1.6); tileBox(737, 305, 823, 306.5, 2.1, H);
  tileBox(738.5, 448.5, 823, 450, 0, H);
  rainShower(738.5, 378, 782, 378);
  towelRail(1000, 410, false, -1);
  box(738.5, 395, 746, 440, 1.05, 1.08, P.quartz, { collide: false });     // shower ledge
  [['#f2efe8', 0], ['#3b3a38', 1], ['#c9b79c', 2]].forEach(([c, i]) =>
    lathe(world, [[0, 0], [0.028, 0], [0.03, 0.17], [0.013, 0.2], [0, 0.2]], std({ color: c, roughness: 0.3 }), X(742), 1.08, Z(405 + i * 14), 20));

  // ---------------------------------------------------------------------------
  // COZINHA – fridge + granite run with sink and cooktop on the east wall (uppers with hood + LED),
  // laundry counter with tank + washer on the west wall (as the plan's "infraestrutura")
  // ---------------------------------------------------------------------------
  item(fridgeB, 1205, 232, 1288, 315, 'w');
  item((w, d) => baseCabB(w, d, { sinkX: -0.45, cooktopX: 0.48, ovenX: 0.48, body: P.greige, door: P.freijo }), 1228, 322, 1290, 505, 'w');
  item((w, d) => upperCabB(w, d, { hoodX: 0.48 }), 1255, 322, 1290, 505, 'w', false);
  box(1288, 322, 1290, 505, 0.9, 1.6, P.quartz, { collide: false });     // stone backsplash
  item((w, d) => baseCabB(w, d, { tankX: 0.33, washerX: -0.47, body: P.greige, door: P.freijo }), 1020, 285, 1068, 460, 'e');
  box(1020, 285, 1022, 460, 0.9, 1.5, P.quartz, { collide: false });
  item((w, d) => upperCabB(w, d), 1020, 285, 1050, 460, 'e', false);

  // ---------------------------------------------------------------------------
  // ESTAR / JANTAR – cream sofa on the east wall, jute rug, round coffee table, TV + floating
  // console on the wood-clad suíte wall, art over the sofa
  // ---------------------------------------------------------------------------
  rug(1035, 572, 1262, 795, P.jute);
  item((w, d) => sofaB(w, d, P.boucleW), 1200, 585, 1290, 790, 'w');
  at(() => roundCoffeeB(0.27), 1112, 700);
  // wood-clad suíte wall (TV wall), from the kitchen cabinets to the façade; the suíte door (485–572) stays open, wood above it
  woodClad(1020, 460, 1023, 483); woodClad(1020, 574, 1023, 797); woodClad(1020, 483, 1023, 574, 2.16);
  tvSlim(X(1023), Z(672), 1.25, 0.72, 1.32);
  item(flutedConsoleB, 1023, 600, 1061, 745, 'e', false);
  wallArt(1290, 688, 0.95, 0.62, 1.58, 'w', artMat('#efe8de', ['#c9b79c', '#9aa889', '#a85a3f', '#e2d3bd']));
  sanca(1020, 520, 1290, 797, 32, 0.12);

  // ---------------------------------------------------------------------------
  // TERRAÇO (2.70 m) – round table with two cane chairs, potted plant, built-in bench on the east
  // ---------------------------------------------------------------------------
  at(roundTableB, 1200, 890, 0, 0.4);
  at(caneChairB, 1142, 918, Math.PI / 2 - 0.25);
  at(caneChairB, 1192, 838, 0.15);
  { const pl = plantB(0, 0, 0.9, P.terracotta); pl.position.set(X(1015), 0, Z(930)); world.add(pl); }
  worldRb(1224, 828, 1287, 965, 0, 0.42, P.walnut, 0.01);
  worldRb(1228, 832, 1283, 961, 0.42, 0.5, P.outdoor, 0.03);
  colliders.push({ x0: X(1224), x1: X(1287), z0: Z(828), z1: Z(965) });

}
